import React, { useState } from 'react';
import { View, Text, Pressable, ViewStyle } from 'react-native';

export type TabItem = {
  title: string;
  content: React.ReactNode;
};

type HorizontalTabsProps = {
  tabs: TabItem[];
  initialTabIndex?: number;
  style?: ViewStyle;
};

const HorizontalTabs = ({ tabs, initialTabIndex = 0 }: HorizontalTabsProps) => {
  const [activeTabIndex, setActiveTabIndex] = useState(
    initialTabIndex < tabs.length ? initialTabIndex : 0,
  );

  if (!tabs || !Array.isArray(tabs) || tabs.length === 0) {
    return (
      <View className="items-center justify-center p-4">
        <Text className="text-red-500">Tab data is not provided or invalid.</Text>
      </View>
    );
  }

  return (
    <View className="flex-1 flex-col">
      <View className="flex-row border-b border-gray-200 bg-linen">
        {tabs.map((tab, index) => (
          <Pressable
            key={tab.title}
            onPress={() => setActiveTabIndex(index)}
            className={`flex-1 items-center justify-center px-4 py-3
                        ${activeTabIndex === index ? 'bg-sage' : ''}`}
          >
            <Text className={`text-center text-xl font-bold text-ocean`}>{tab.title}</Text>
          </Pressable>
        ))}
      </View>

      <View className="flex-1 pt-4">{tabs[activeTabIndex] && tabs[activeTabIndex].content}</View>
    </View>
  );
};

export default HorizontalTabs;
