import { ArrowRight } from 'lucide-react-native';
import { View } from 'react-native';
import { Pressable } from 'react-native';
import SmartImage from '@/app/components/ui/smart-image';
import { router } from 'expo-router';
import { Text } from 'react-native';
import { useTranslation } from 'react-i18next';
import type { NewsItemInList } from '@/features/news/types';

interface NewsItemProps {
  item: NewsItemInList;
}

const NewsItem = ({ item }: NewsItemProps) => {
  const { t } = useTranslation();

  return (
    <Pressable
      onPress={() => router.push(`/(app)/news/${item.id}`)}
    >
      <View className="mb-4 min-h-20 flex-row overflow-hidden rounded-xl border border-gray-200 bg-linen shadow-lg">
        <SmartImage
          source={{ uri: item.featuredImage }}
          className="h-full w-28"
          resizeMode="cover"
        />
        <View className="flex-1 flex-col items-start justify-start gap-2 px-4 py-2">
          <Text className="text-xs text-ocean opacity-60">
            {new Date(item.createdAt).toLocaleDateString()}
          </Text>
          <Text className="mb-1 text-base font-bold text-ocean">{item.title}</Text>
        </View>
        <View className="absolute bottom-2 right-2 flex-row items-center gap-2">
          <Text className="text-xs text-sage ">{t('general.read')}</Text>
          <ArrowRight size={14} color="#9FAA87" />
        </View>
      </View>
    </Pressable>
  );
};

export default NewsItem;
