import React from 'react';
import { View, Text, ActivityIndicator, FlatList } from 'react-native';
import NewsItem from './news-list-item';
import { useNewsQuery } from '@/features/news/useNewsQuery';
import type { NewsItemInList } from '@/features/news/types';

const LatestNews = () => {
  const { data, isLoading, error, refetch } = useNewsQuery(3);

  if (isLoading) {
    return (
      <View className="flex-1 items-center justify-center py-4">
        <ActivityIndicator size="large" color="#fff" />
      </View>
    );
  }

  if (error) {
    const errorMessage = error instanceof Error ? error.message : 'An error occurred while loading news';
    return (
      <View className="mt-2 rounded-lg bg-red-900/30 p-4">
        <Text className="text-white">Error loading news: {errorMessage}</Text>
      </View>
    );
  }

  if (data?.length === 0) {
    return (
      <View className="py-4">
        <Text className="text-center text-white">No news available</Text>
      </View>
    );
  }

  return (
    <FlatList
      data={data}
      renderItem={({ item }: { item: NewsItemInList }) => <NewsItem item={item} />}
      keyExtractor={(item: NewsItemInList) => item.id}
      scrollEnabled={false}
      onRefresh={refetch}
      refreshing={isLoading}
    />
  );
};

export default LatestNews;
