import React, { useState } from 'react';
import { Text, View, Pressable } from 'react-native';
import { router, useLocalSearchParams, useFocusEffect } from 'expo-router';
import { ChevronLeft } from 'lucide-react-native';
import * as yup from 'yup';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { useTranslation } from 'react-i18next';

import { useAuth } from '@/features/auth';
import { ScreenContainer, TextField, FormError } from '@/app/components/ui/exports';

const ResetPasswordSchema = (t: any) =>
  yup.object().shape({
    password: yup
      .string()
      .required(t('resetPassword.errors.passwordRequired'))
      .min(6, t('resetPassword.errors.passwordMinLength')),
    confirmPassword: yup
      .string()
      .required(t('resetPassword.errors.confirmPasswordRequired'))
      .oneOf([yup.ref('password')], t('resetPassword.errors.confirmPasswordMismatch')),
  });

const ResetPasswordScreen = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const { resetPassword } = useAuth();
  const { t } = useTranslation();
  const { token } = useLocalSearchParams<{ token: string }>();

  const {
    control,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm({
    defaultValues: {
      password: '',
      confirmPassword: '',
    },
    resolver: yupResolver(ResetPasswordSchema(t)),
  });

  // Очищаем форму и состояние при фокусе на экране (кроме случая успеха)
  useFocusEffect(
    React.useCallback(() => {
      if (!success) {
        reset();
        setError('');
        setIsLoading(false);
      }
    }, [reset, success]),
  );

  const onSubmit = async ({
    password,
    confirmPassword,
  }: {
    password: string;
    confirmPassword: string;
  }) => {
    if (!token) {
      setError(t('resetPassword.errors.invalidToken'));
      return;
    }

    try {
      setIsLoading(true);
      setError('');
      setSuccess(false);

      await resetPassword(token, password);

      setSuccess(true);
      reset();
    } catch (err) {
      const errorMessage =
        typeof err === 'string'
          ? err
          : err instanceof Error
            ? err.message
            : t('resetPassword.errors.submitError');

      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  if (!token) {
    return (
      <ScreenContainer>
        <View className="mt-4 w-full flex-1 flex-col justify-start p-6">
          <View className="relative mb-8 w-full flex-row items-center justify-center gap-4">
            <Pressable className="absolute left-0" onPress={() => router.back()}>
              <ChevronLeft size={24} color="white" />
            </Pressable>

            <Text className="text-center font-rubik-medium text-3xl tracking-wide text-white">
              {t('resetPassword.title')}
            </Text>
          </View>

          <View className="mb-8 flex-row items-center gap-2 rounded-lg bg-red-100 px-3 py-2">
            <Text className="flex-1 font-rubik text-sm text-red-600">
              {t('resetPassword.errors.invalidToken')}
            </Text>
          </View>

          <Pressable
            className="mb-8 rounded-full bg-primary-100 py-4"
            onPress={() => router.replace('/(auth)/sign-in')}
          >
            <Text className="text-center font-rubik-medium text-lg text-black">
              {t('resetPassword.backToLogin')}
            </Text>
          </Pressable>
        </View>
      </ScreenContainer>
    );
  }

  return (
    <ScreenContainer loading={isLoading}>
      <View className="mt-4 w-full flex-1 flex-col justify-start p-6">
        <View className="relative mb-8 w-full flex-row items-center justify-center gap-4">
          <Pressable className="absolute left-0" onPress={() => router.back()}>
            <ChevronLeft size={24} color="white" />
          </Pressable>

          <Text className="text-center font-rubik-medium text-3xl tracking-wide text-white">
            {t('resetPassword.title')}
          </Text>
        </View>

        {success ? (
          <View className="mb-8 flex-row items-center gap-2 rounded-lg bg-green-100 px-3 py-2">
            <Text className="flex-1 font-rubik text-sm text-green-600">
              {t('resetPassword.successMessage')}
            </Text>
          </View>
        ) : (
          <>
            <Text className="mb-6 text-center text-lg leading-relaxed text-linen/90">
              {t('resetPassword.description')}
            </Text>

            <FormError error={error} />

            <View className="mb-10 flex flex-col gap-4">
              <TextField
                label={t('resetPassword.password')}
                name="password"
                control={control}
                error={errors.password}
                placeholder={t('resetPassword.placeholder.password')}
                secureTextEntry
              />

              <TextField
                label={t('resetPassword.confirmPassword')}
                name="confirmPassword"
                control={control}
                error={errors.confirmPassword}
                placeholder={t('resetPassword.placeholder.confirmPassword')}
                secureTextEntry
              />
            </View>

            <Pressable
              className="mb-8 rounded-full bg-primary-100 py-4"
              onPress={handleSubmit(onSubmit)}
              disabled={isLoading}
            >
              <Text className="text-center font-rubik-medium text-lg text-black">
                {isLoading ? t('resetPassword.resetting') : t('resetPassword.submit')}
              </Text>
            </Pressable>
          </>
        )}

        {success && (
          <Pressable
            className="mb-8 rounded-full bg-primary-100 py-4"
            onPress={() => router.replace('/(auth)/sign-in')}
          >
            <Text className="text-center font-rubik-medium text-lg text-black">
              {t('resetPassword.backToLogin')}
            </Text>
          </Pressable>
        )}
      </View>
    </ScreenContainer>
  );
};

export default ResetPasswordScreen;
