import React, { useEffect } from 'react';
import { Tabs } from 'expo-router';
import { Home, User, BookOpen, Sparkles } from 'lucide-react-native';
import { View, Pressable, Dimensions } from 'react-native';
import type { BottomTabBarProps } from '@react-navigation/bottom-tabs';
import Animated, { useAnimatedStyle, withTiming, useSharedValue } from 'react-native-reanimated';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useAuth } from '@/features/auth';

const activeColor = '#9FAA87';
const inactiveColor = '#FFFFFF';
const indicatorColor = '#9FAA87';

const { width: screenWidth } = Dimensions.get('window');

// Custom Tab Bar Component
function CustomTabBar({ state, descriptors, navigation }: BottomTabBarProps) {
  const { session } = useAuth();

  // Filter out hidden tabs and calculate visible tabs
  const visibleRoutes = state.routes.filter(route => {
    if (route.name === 'lena-chat' && !session?.user?.hasLicense) {
      return false;
    }
    return true;
  });

  const totalTabs = visibleRoutes.length;
  const tabWidth = totalTabs > 0 ? screenWidth / totalTabs : screenWidth;
  const indicatorWidth = tabWidth - 40;
  const translateX = useSharedValue(0);

  useEffect(() => {
    // Find the actual index in visible tabs
    const visibleIndex = visibleRoutes.findIndex(route => route.name === state.routes[state.index].name);
    const actualIndex = visibleIndex >= 0 ? visibleIndex : 0;

    translateX.value = withTiming(actualIndex * tabWidth + 20, {
      duration: 150,
    });
  }, [state.index, tabWidth, translateX, visibleRoutes]);

  const animatedIndicatorStyle = useAnimatedStyle(() => {
    return {
      transform: [{ translateX: translateX.value }],
    };
  });

  return (
    <View className="relative border-t  border-black-100/20">
      {/* Animated Indicator */}
      <Animated.View
        style={[
          {
            position: 'absolute',
            top: -1,
            height: 2,
            width: indicatorWidth,
            backgroundColor: indicatorColor,
          },
          animatedIndicatorStyle,
        ]}
      />
      {/* Tab Buttons */}
      <View className="h-20 flex-row items-center  justify-center py-2">
        {state.routes.map((route, index) => {
          const { options } = descriptors[route.key];
          const label = options.tabBarLabel ?? options.title ?? route.name;
          const isFocused = state.index === index;

          if (route.name === 'lena-chat' && !session?.user?.hasLicense) {
            return null;
          }

          const onPress = () => {
            const event = navigation.emit({
              type: 'tabPress',
              target: route.key,
              canPreventDefault: true,
            });

            if (!isFocused && !event.defaultPrevented) {
              if (route.name === 'lena-chat-tab') {
                navigation.navigate('/lena-chat/new');
              } else {
                navigation.navigate(route.name, route.params);
              }
            }
          };

          const onLongPress = () => {
            navigation.emit({
              type: 'tabLongPress',
              target: route.key,
            });
          };

          const TabBarIcon = options.tabBarIcon;

          return (
            <Pressable
              key={route.key}
              accessibilityRole="button"
              accessibilityState={isFocused ? { selected: true } : {}}
              accessibilityLabel={options.tabBarAccessibilityLabel ?? String(label)}
              onPress={onPress}
              onLongPress={onLongPress}
              className="h-full flex-1 items-center justify-center"
            >
              {TabBarIcon ? (
                <TabBarIcon
                  focused={isFocused}
                  color={isFocused ? activeColor : inactiveColor}
                  size={24}
                />
              ) : (
                <View className="h-6 w-6" />
              )}
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

export default function DashboardLayout() {
  return (
    <SafeAreaView edges={['top', 'bottom']} className="flex-1 justify-center bg-ocean-dark">
      <Tabs
        screenOptions={{
          headerShown: false,
          animation: 'shift',
        }}
        tabBar={props => <CustomTabBar {...props} />}
      >
        <Tabs.Screen
          name="index"
          options={{
            title: 'Home',
            tabBarIcon: ({ color, size }) => <Home size={size} color={color} />,
          }}
        />
        <Tabs.Screen
          name="education"
          options={{
            title: 'Education',
            tabBarIcon: ({ color, size }) => <BookOpen size={size} color={color} />,
          }}
        />
        <Tabs.Screen
          name="lena-chat"
          options={{
            title: 'Lena AI',
            tabBarIcon: ({ color, size }) => <Sparkles size={size} color={color} />,
          }}
        />
        <Tabs.Screen
          name="profile"
          options={{
            title: 'Profile',
            tabBarIcon: ({ color, size }) => <User size={size} color={color} />,
          }}
        />
      </Tabs>
    </SafeAreaView>
  );
}
