import { View, Text, FlatList, ActivityIndicator, Pressable } from 'react-native';
import { useCoursesQuery } from '@/features/education';
import { useCertificatesQuery } from '@/features/education/use-certificate';
import { router } from 'expo-router';
import { CourseStatus } from '@/features/education/types';
import React from 'react';
import SmartImage from '@/app/components/ui/smart-image';
import { useTranslation } from 'react-i18next';

interface CoursesListProps {
  courseStatus: CourseStatus;
}

const CoursesList = ({ courseStatus }: CoursesListProps) => {
  const { t } = useTranslation();
  const { data: courses, isLoading, error, refetch, isRefetching } = useCoursesQuery(courseStatus);
  const { data: certificates } = useCertificatesQuery();

  const handleCoursePress = course => {
    router.push({
      pathname: `education/course/${course.courseId}`,
      params: {
        courseString: JSON.stringify(course),
      },
    });
  };

  const CourseItem = ({ course, certificates, type }) => {
    const certificate = certificates.find(i => i.courseId === course.courseId);
    const completedDate = certificate?.completedOn
      ? new Date(certificate.completedOn).toISOString().split('T')[0]
      : null;

    return (
      <Pressable onPress={() => handleCoursePress(course)}>
        <View className="mb-4 min-h-20 flex-row overflow-hidden rounded-xl border border-gray-200 bg-linen shadow-lg">
          <SmartImage
            source={{ uri: course.imageUrl }}
            className="h-full w-28"
            resizeMode="cover"
          />
          <View className="flex-1 pb-2 pl-4 pr-2 pt-2">
            <Text className="mb-2 text-xl font-bold text-ocean-dark">{course.title}</Text>
            {type === 'completed' && certificate && (
              <>
                <Text className="text-lg font-semibold text-ocean-dark">
                  {t('coursesList.finished')}: {completedDate}
                </Text>
                <Text className="text-lg font-semibold text-ocean-dark">
                  {t('coursesList.score')}: {certificate.score}%
                </Text>
              </>
            )}
          </View>
        </View>
      </Pressable>
    );
  };

  if (isLoading && !courses) {
    return (
      <View className="flex-1 items-center justify-center p-4">
        <ActivityIndicator size="large" color="#4f46e5" />
        <Text className="mt-2 text-white">{t('coursesList.loading')}</Text>
      </View>
    );
  }

  return (
    <FlatList
      data={courses || []}
      renderItem={data => (
        <CourseItem course={data.item} certificates={certificates} type={courseStatus} />
      )}
      keyExtractor={item => item.courseId}
      className="mt-2 px-2"
      ListEmptyComponent={
        !isLoading && !error && courses?.length === 0 ? (
          <View className="mt-10 flex-1 items-center justify-center">
            <Text className="text-lg text-white">{t('coursesList.empty')}</Text>
          </View>
        ) : null
      }
      onRefresh={refetch}
      refreshing={isRefetching}
    />
  );
};

export default CoursesList;
