import type { ChatRequestOptions, CreateMessage, Message } from 'ai';
import { memo } from 'react';
import { Pressable, View, Text } from 'react-native';
import { ArrowRight } from 'lucide-react-native';

interface SuggestedActionsProps {
  chatId: string;
  append: (
    message: Message | CreateMessage,
    chatRequestOptions?: ChatRequestOptions,
  ) => Promise<string | null | undefined>;
}

function PureSuggestedActions({ chatId, append }: SuggestedActionsProps) {
  const suggestedActions = [
    {
      action: 'Jag är ny som god man. Vad gör jag nu?',
    },
    {
      action: 'Finns det någon metod för en god man?',
    },
    {
      action: 'Vilka är gode mannens gränser?',
    },
    {
      action: 'Jag ska sälja min huvudmans bostad. Hur gör jag?',
    },
    {
      action: 'Varför ska jag ansöka om merkostnadsersättning för min huvudman?',
    },
  ];

  return (
    <View className="flex flex-col gap-3">
      {suggestedActions.map((suggestedAction, index) => (
        <Pressable
          key={suggestedAction.action}
          onPress={async () => {
            // router.push(`/lena-chat/${chatId}`);

            append({
              role: 'user',
              content: suggestedAction.action,
            });
          }}
          className="h-auto w-full flex-1 flex-row items-center justify-between gap-1 rounded-xl border bg-linen px-4 py-3.5 text-left text-sm"
        >
          <Text className="max-w-[90%] font-medium text-ocean">{suggestedAction.action}</Text>
          <ArrowRight size={20} color="#9FAA87" />
        </Pressable>
      ))}
    </View>
  );
}

const SuggestedActions = memo(PureSuggestedActions, () => true);

export default SuggestedActions;
