import React, { useState } from 'react';
import { Text, View, Pressable } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { ChevronLeft } from 'lucide-react-native';
import * as yup from 'yup';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { useTranslation } from 'react-i18next';

import { useAuth } from '@/features/auth';
import { ScreenContainer, TextField, FormError } from '@/app/components/ui/exports';

const ForgotPasswordSchema = (t: any) =>
  yup.object().shape({
    email: yup
      .string()
      .email(t('forgotPassword.errors.emailInvalid'))
      .required(t('forgotPassword.errors.emailRequired')),
  });

const ForgotPasswordScreen = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const { requestPasswordReset } = useAuth();
  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm({
    defaultValues: {
      email: '',
    },
    resolver: yupResolver(ForgotPasswordSchema(t)),
  });

  useFocusEffect(
    React.useCallback(() => {
      reset();
      setError('');
      setSuccess(false);
      setIsLoading(false);
    }, [reset]),
  );

  const onSubmit = async ({ email }: { email: string }) => {
    try {
      setIsLoading(true);
      setError('');
      setSuccess(false);

      await requestPasswordReset(email);

      setSuccess(true);
      reset();
    } catch (err) {
      const errorMessage =
        typeof err === 'string'
          ? err
          : err instanceof Error
            ? err.message
            : t('forgotPassword.errors.submitError');

      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ScreenContainer loading={isLoading}>
      <View className="mt-4 w-full flex-1 flex-col justify-start p-6">
        <View className="relative mb-8 w-full flex-row items-center justify-center gap-4">
          <Pressable className="absolute left-0" onPress={() => router.back()}>
            <ChevronLeft size={24} color="white" />
          </Pressable>

          <Text className="text-center font-rubik-medium text-3xl tracking-wide text-white">
            {t('forgotPassword.title')}
          </Text>
        </View>

        {success ? (
          <View className="mb-8 flex-row items-center gap-2 rounded-lg bg-green-100 px-3 py-2">
            <Text className="flex-1 font-rubik text-sm text-green-600">
              {t('forgotPassword.successMessage')}
            </Text>
          </View>
        ) : (
          <>
            <Text className="mb-6 text-center text-lg leading-relaxed text-linen/90">
              {t('forgotPassword.description')}
            </Text>

            <FormError error={error} />

            <View className="mb-10 flex flex-col gap-4">
              <TextField
                label={t('forgotPassword.email')}
                name="email"
                control={control}
                error={errors.email}
                placeholder={t('forgotPassword.placeholder.email')}
                keyboardType="email-address"
                autoCapitalize="none"
              />
            </View>

            <Pressable
              className="mb-8 rounded-full bg-primary-100 py-4"
              onPress={handleSubmit(onSubmit)}
              disabled={isLoading}
            >
              <Text className="text-center font-rubik-medium text-lg text-black">
                {isLoading ? t('forgotPassword.sending') : t('forgotPassword.submit')}
              </Text>
            </Pressable>
          </>
        )}

        <View className="flex-row justify-center">
          <Text className="font-rubik text-white">{t('forgotPassword.rememberPassword')} </Text>
          <Pressable onPress={() => router.back()}>
            <Text className="font-rubik-medium text-primary-100">
              {t('forgotPassword.backToLogin')}
            </Text>
          </Pressable>
        </View>
      </View>
    </ScreenContainer>
  );
};

export default ForgotPasswordScreen;
