import { View, Text } from 'react-native';
import { useTranslation } from 'react-i18next';

const CertificateListItem = ({ item }) => {
  const { t } = useTranslation();

  const formattedDate = new Date(item.completedOn).toISOString().split('T')[0];

  return (
    <View className="h-fit flex-row overflow-hidden rounded-lg border border-black-100/20 bg-linen p-2">
      <View className="flex-1">
        <Text className="mb-1 text-lg font-bold text-ocean">{item.title}</Text>

        <View className="flex-row justify-between">
          <Text className="text-lg text-ocean">{t('certificateItem.title')}</Text>
          <Text className="text-lg text-ocean">{formattedDate}</Text>
        </View>

        <View className="flex-row justify-between">
          <Text className="text-lg text-ocean">{t('certificateItem.score')}</Text>
          <Text className="text-lg text-ocean">{item.score}%</Text>
        </View>
      </View>
    </View>
  );
};

export default CertificateListItem;
