import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Check, AlertCircle } from 'lucide-react-native';

interface CheckboxProps {
  checked: boolean;
  onToggle: () => void;
  label: string;
  error?: string;
}

export const Checkbox: React.FC<CheckboxProps> = ({ checked, onToggle, label, error }) => {
  return (
    <View>
      <Pressable
        className="flex-row items-start gap-3"
        onPress={onToggle}
        hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
      >
        <View
          className={`h-5 w-5 items-center justify-center rounded border ${
            checked ? 'bg-primary-100 border-primary-100' : 'border-gray-400'
          }`}
        >
          {checked && <Check size={14} color="black" />}
        </View>
        <Text className="flex-1 text-lg leading-5 text-white font-rubik">
          {label}
        </Text>
      </Pressable>
      {error && (
        <View className="mt-2 flex-row items-center gap-2 px-2 py-2">
          <AlertCircle size={16} color="#dc2626" />
          <Text className="flex-1 text-sm text-red-600 font-rubik">
            {error}
          </Text>
        </View>
      )}
    </View>
  );
};
