import React, { useState } from 'react';
import { Text, View, Pressable, Alert, ScrollView, Platform } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { ChevronLeft } from 'lucide-react-native';
import * as yup from 'yup';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { useTranslation } from 'react-i18next';

import { useAuth } from '@/features/auth';
import { ScreenContainer, TextField } from '@/app/components/ui/exports';

const SignInSchema = (t: any) =>
  yup.object().shape({
    email: yup
      .string()
      .email(t('signin.errors.emailInvalid'))
      .required(t('signin.errors.emailRequired')),
    password: yup
      .string()
      .required(t('signin.errors.passwordRequired'))
      .min(6, t('signin.errors.passwordMinLength')),
  });

const SignInScreen = () => {
  const [isLoading, setIsLoading] = useState(false);

  const { signIn } = useAuth();

  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm({
    defaultValues: {
      email: '',
      password: '',
    },
    resolver: yupResolver(SignInSchema(t)),
  });

  useFocusEffect(
    React.useCallback(() => {
      reset();
      setIsLoading(false);
    }, [reset]),
  );

  const onSubmit = async ({ email, password }: { email: string; password: string }) => {
    try {
      setIsLoading(true);
      await signIn(email, password);
    } catch (err) {
      const errorMessage =
        typeof err === 'string'
          ? err
          : err instanceof Error
            ? err.message
            : t('signin.errors.signInFailed');

      Alert.alert(t('alerts.error'), errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ScreenContainer loading={isLoading}>
      <ScrollView
        className="flex-1"
        contentContainerStyle={{
          flexGrow: 1,
          paddingBottom: 20,
        }}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode="interactive"
        automaticallyAdjustKeyboardInsets={Platform.OS === 'ios'}
      >
        <View className="mt-4 w-full flex-1 flex-col justify-start p-6">
          <View className="relative mb-8 w-full flex-row items-center justify-center gap-4">
            <Pressable className="absolute left-0" onPress={() => router.push('/')}>
              <ChevronLeft size={24} color="white" />
            </Pressable>

            <Text className="text-center font-rubik-medium text-3xl tracking-wide text-white">
              {t('signin.title')}
            </Text>
          </View>

          <View className="mb-10 mt-8 flex flex-col gap-4">
            <TextField
              label={t('signin.email')}
              name="email"
              control={control}
              error={errors.email}
              placeholder={t('signin.placeholder.email')}
              keyboardType="email-address"
              autoCapitalize="none"
            />

            <TextField
              label={t('signin.password')}
              name="password"
              control={control}
              error={errors.password}
              placeholder={t('signin.placeholder.password')}
              secureTextEntry
            />
          </View>

          <Pressable
            className="mb-8 rounded-full bg-primary-100 py-4"
            onPress={handleSubmit(onSubmit)}
            disabled={isLoading}
          >
            <Text className="text-center font-rubik-medium text-lg text-black">
              {isLoading ? t('signin.loading') : t('signin.submit')}
            </Text>
          </Pressable>

          <View className="mb-4 flex-row justify-center">
            <Text className="font-rubik text-white">{t('signin.noAccount')} </Text>
            <Pressable onPress={() => router.push('/sign-up')}>
              <Text className="font-rubik-medium text-primary-100">{t('signin.signUp')}</Text>
            </Pressable>
          </View>

          <View className="flex-row justify-center">
            <Text className="font-rubik text-white">{t('signin.forgotPassword')} </Text>
            <Pressable onPress={() => router.push('/forgot-password')}>
              <Text className="font-rubik-medium text-primary-100">
                {t('signin.resetPassword')}
              </Text>
            </Pressable>
          </View>
        </View>
      </ScrollView>
    </ScreenContainer>
  );
};

export default SignInScreen;
