import { useMemo } from 'react';
import { View, Text, Pressable, SafeAreaView, ScrollView } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCourseByIdQuery } from '@/features/education';
import VimeoWebPlayer from '@/app/components/ui/vimeo-web-player';
import React from 'react';
import { ArrowLeft } from 'lucide-react-native';
import QuestionForm from '@/app/components/education/question-form';
import { Chapter } from '@/features/education/types';
import { useSubmitAnswersMutation } from '@/features/education';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import HtmlRenderer from '@/app/components/ui/html-renderer';

const LessonScreen: React.FC = () => {
  const { courseId, lessonId } = useLocalSearchParams();
  const { mutateAsync } = useSubmitAnswersMutation();
  const router = useRouter();

  const { data: course, isLoading, error } = useCourseByIdQuery(courseId);

  const activeChapter = useMemo<Chapter | undefined>(() => {
    if (!course?.chapters?.length) {
      return undefined;
    }
    return course.chapters.find(chapter => chapter.chapterId == lessonId);
  }, [course, lessonId]);

  const chapterIsDone = useMemo(() => {
    return activeChapter?.questions.every(
      q => Array.isArray(q.userAnswerOptionIds) && q.userAnswerOptionIds.length > 0,
    );
  }, [activeChapter?.questions]);

  const handleNextLesson = (): void => {
    if (!course?.chapters?.length) return;

    const currentIndex = course.chapters.findIndex(ch => ch.chapterId === Number(lessonId));
    const nextChapter = course.chapters[currentIndex + 1];

    if (nextChapter) {
      router.replace(`/(course)/${courseId}/lesson/${nextChapter.chapterId}`);
    } else {
      router.replace(`/(course)/${courseId}/completion`);
    }
  };

  if (isLoading) {
    return (
      <SafeAreaView
        className="flex-1 items-center justify-center"
        style={{ backgroundColor: '#2a3d4c' }}
      >
        <Text className="text-lg text-linen">{t('lessonScreen.loading')}</Text>
      </SafeAreaView>
    );
  }

  if (error || !activeChapter) {
    return (
      <SafeAreaView
        className="flex-1 items-center justify-center"
        style={{ backgroundColor: '#2a3d4c' }}
      >
        <View className="h-fit flex-row items-center justify-start gap-2 self-stretch border-b border-black-100/20 bg-ocean-dark px-4 py-4">
          <Pressable onPress={() => router.back()}>
            <ArrowLeft size={24} color="#FAF3ED" />
          </Pressable>
        </View>
        <View className="flex-1 items-center justify-center">
          <Text className="text-xl text-linen">{t('lessonScreen.notFound')}</Text>
          <Pressable
            className="mt-4 items-center rounded-lg bg-gray-500 p-3 shadow"
            onPress={() => router.push(`/(course)/${courseId}/outline`)}
          >
            <Text className="text-md font-semibold text-white">
              {t('lessonScreen.goToOutline')}
            </Text>
          </Pressable>
        </View>
      </SafeAreaView>
    );
  }

  const handleQuizSubmit = async answers => {
    await mutateAsync({ courseId, answers });
    handleNextLesson();
  };

  const isLastLesson = useMemo(() => {
    const currentLessonIndex = course?.chapters.findIndex(c => c.chapterId === lessonId) ?? -1;
    return currentLessonIndex === (course?.chapters.length ?? 0) - 1;
  }, [course, lessonId]);

  return (
    <SafeAreaView className="flex-1 bg-ocean">
      <View className="h-fit flex-row items-center justify-start gap-2 border-b border-black-100/20 bg-ocean-dark px-2 py-4">
        <Pressable onPress={() => router.back()}>
          <ArrowLeft size={24} color="#FAF3ED" />
        </Pressable>
        <Text className="text-2xl font-bold text-linen">{activeChapter.title}</Text>
        <LinearGradient
          colors={['#000', 'transparent']}
          style={{
            position: 'absolute',
            bottom: -20,
            left: 0,
            right: 0,
            height: 20,
            zIndex: 100,
          }}
        />
      </View>

      <ScrollView className="px-2 py-8">
        {activeChapter.videoUrl && (
          <View className="mb-4 overflow-hidden rounded-lg">
            <VimeoWebPlayer videoUrl={activeChapter.videoUrl} />
          </View>
        )}

        <View className="mb-6 rounded-lg bg-linen p-4 shadow">
          <HtmlRenderer html={activeChapter.description} />
        </View>

        {activeChapter.questions && activeChapter.questions.length > 0 && (
          <QuestionForm
            questions={activeChapter.questions}
            onSubmit={handleQuizSubmit}
            hideSubmitButton={!chapterIsDone}
          />
        )}

        {chapterIsDone && (
          <Pressable onPress={handleNextLesson} className="mt-8 overflow-hidden rounded-lg">
            <LinearGradient
              colors={['#A0A0A0', '#A0A0A0']}
              className="rounded-lg shadow"
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
            >
              <View className="flex-row items-center justify-center px-5 py-3">
                <Text className="mr-2 text-lg font-bold text-white">{t('lessonScreen.next')}</Text>
                <MaterialCommunityIcons name="send" size={20} color="white" />
              </View>
            </LinearGradient>
          </Pressable>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

export default LessonScreen;
