import React, { useState } from 'react';
import {
  View,
  TextInput,
  Pressable,
  NativeSyntheticEvent,
  TextInputContentSizeChangeEventData,
  Platform,
} from 'react-native';
import { ArrowUp } from 'lucide-react-native';

interface ChatInputProps {
  onSubmit: (text: string) => void;
  placeholder?: string;
  disabled?: boolean;
  maxHeight?: number;
  minHeight?: number;
  value?: string;
  onChangeText?: (text: string) => void;
}

const ChatInput: React.FC<ChatInputProps> = ({
  onSubmit,
  placeholder = 'Type your message...',
  disabled = false,
  maxHeight = 180,
  minHeight = 44,
  value,
  onChangeText,
}) => {
  const [internalText, setInternalText] = useState('');
  const [inputHeight, setInputHeight] = useState(minHeight);

  // Use external value and onChangeText if provided, otherwise use internal state
  const text = value !== undefined ? value : internalText;
  const setText = onChangeText || setInternalText;

  const handleContentSizeChange = (
    e: NativeSyntheticEvent<TextInputContentSizeChangeEventData>,
  ) => {
    const height = e.nativeEvent.contentSize.height;
    if (height < maxHeight) {
      setInputHeight(Math.max(minHeight, height));
    } else {
      setInputHeight(maxHeight);
    }
  };

  const handlePress = () => {
    const trimmed = text.trim();
    if (!trimmed) return;
    onSubmit(trimmed);
    // Only clear internal state if not using external value
    if (value === undefined) {
      setInternalText('');
    }
    setInputHeight(minHeight); // reset height
  };

  const isSubmitDisabled = !text.trim() || disabled;
  const buttonColor = isSubmitDisabled ? '#888' : '#ffffff';

  return (
    <View className="relative mx-4 mb-4 flex-row items-end rounded-[30px] border border-black-100/20 bg-linen px-4 pb-1 pt-2">
      <TextInput
        className="flex-1 pr-10 text-lg text-black"
        placeholder={placeholder}
        placeholderTextColor="#888"
        value={text}
        onChangeText={setText}
        multiline
        textAlignVertical="top"
        editable={!disabled}
        onContentSizeChange={handleContentSizeChange}
        style={{
          minHeight,
          maxHeight,
          height: inputHeight,
          paddingTop: Platform.OS === 'ios' ? 10 : 8,
          paddingBottom: Platform.OS === 'ios' ? 10 : 8,
        }}
      />

      <Pressable
        onPress={handlePress}
        disabled={isSubmitDisabled}
        className={`absolute bottom-3 right-3 rounded-full bg-ocean p-2 transition-opacity ${
          isSubmitDisabled ? 'opacity-40' : 'opacity-100'
        }`}
      >
        <ArrowUp size={20} color={buttonColor} />
      </Pressable>
    </View>
  );
};

export default ChatInput;
