import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { Text, View, Pressable, ScrollView, Platform } from 'react-native';
import { useTranslation } from 'react-i18next';
import { router, useFocusEffect } from 'expo-router';
import { ChevronLeft } from 'lucide-react-native';
import { useAuth } from '@/features/auth';
import { ScreenContainer, TextField, FormError, Checkbox } from '@/app/components/ui/exports';

const SignUpSchema = (t: any) =>
  yup.object().shape({
    name: yup.string().required(t('signup.errors.nameRequired')),
    lastName: yup.string().required(t('signup.errors.lastNameRequired')),
    email: yup
      .string()
      .email(t('signup.errors.emailInvalid'))
      .required(t('signup.errors.emailRequired')),
    securityNumber: yup.string().required(t('signup.errors.securityNumberRequired')),
    password: yup
      .string()
      .required(t('signup.errors.passwordRequired'))
      .min(6, t('signup.errors.passwordMinLength')),
    confirmPassword: yup
      .string()
      .required(t('signup.errors.confirmPasswordRequired'))
      .oneOf([yup.ref('password')], t('signup.errors.confirmPasswordMismatch')),
    gdprConsent: yup.boolean().oneOf([true], t('signup.errors.gdprConsentRequired')),
  });

export default function SignUp() {
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { signUp } = useAuth();
  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    formState: { errors },
    reset,
    watch,
    setValue,
  } = useForm({
    defaultValues: {
      name: '',
      lastName: '',
      email: '',
      securityNumber: '',
      password: '',
      confirmPassword: '',
      gdprConsent: false,
    },
    resolver: yupResolver(SignUpSchema(t)),
  });

  const gdprConsent = watch('gdprConsent') || false;

  useFocusEffect(
    React.useCallback(() => {
      reset();
      setError('');
      setIsLoading(false);
    }, [reset]),
  );

  const onSubmit = async (data: {
    email: string;
    password: string;
    name: string;
    lastName: string;
    securityNumber: string;
    gdprConsent?: boolean;
  }) => {
    try {
      setIsLoading(true);

      await signUp(data.email, data.password, data.name, data.lastName, data.securityNumber);

      router.replace('/(app)/dashboard');
    } catch (err) {
      setError(typeof err === 'string' ? err : t('signup.errors.signupFailed'));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ScreenContainer loading={isLoading}>
      <ScrollView
        className="flex-1"
        contentContainerStyle={{
          flexGrow: 1,
          paddingBottom: 20,
        }}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode="interactive"
        automaticallyAdjustKeyboardInsets={Platform.OS === 'ios'}
      >
        <View className="mt-4 w-full flex-1 flex-col justify-start p-6">
          <View className="relative mb-8 w-full flex-row items-center justify-center gap-4">
            <Pressable className="absolute left-0" onPress={() => router.push('/')}>
              <ChevronLeft size={24} color="white" />
            </Pressable>

            <Text className="text-center font-rubik-medium text-3xl tracking-wide text-white">
              {t('signup.title')}
            </Text>
          </View>

          <FormError error={error} />

          <View className="mb-10 flex flex-col gap-4">
            <TextField
              label={t('signup.name')}
              name="name"
              control={control}
              error={errors.name}
              placeholder={t('signup.placeholder.name')}
            />

            <TextField
              label={t('signup.lastName')}
              name="lastName"
              control={control}
              error={errors.lastName}
              placeholder={t('signup.placeholder.lastName')}
            />

            <TextField
              label={t('signup.email')}
              name="email"
              control={control}
              error={errors.email}
              placeholder={t('signup.placeholder.email')}
              keyboardType="email-address"
              autoCapitalize="none"
            />

            <TextField
              label={t('signup.securityNumber')}
              name="securityNumber"
              control={control}
              error={errors.securityNumber}
              placeholder={t('signup.placeholder.securityNumber')}
            />

            <TextField
              label={t('signup.password')}
              name="password"
              control={control}
              error={errors.password}
              placeholder={t('signup.placeholder.password')}
              secureTextEntry
            />

            <TextField
              label={t('signup.confirmPassword')}
              name="confirmPassword"
              control={control}
              error={errors.confirmPassword}
              placeholder={t('signup.placeholder.confirmPassword')}
              secureTextEntry
            />
            <Checkbox
              checked={gdprConsent}
              onToggle={() => setValue('gdprConsent', !gdprConsent)}
              label={t('signup.gdprConsent')}
              error={errors.gdprConsent?.message}
            />
          </View>

          <Pressable
            className="mb-8 rounded-full bg-primary-100 py-4"
            onPress={handleSubmit(onSubmit)}
            disabled={isLoading}
          >
            <Text className="text-center font-rubik-medium text-lg text-black">
              {isLoading ? t('signup.loading') : t('signup.submit')}
            </Text>
          </Pressable>

          <View className="flex-row justify-center">
            <Text className="font-rubik text-white">{t('signup.alreadyAccount')} </Text>
            <Pressable onPress={() => router.push('/sign-in')}>
              <Text className="font-rubik-medium text-primary-100">{t('signup.login')}</Text>
            </Pressable>
          </View>
        </View>
      </ScrollView>
    </ScreenContainer>
  );
}
