import { View, Text, SafeAreaView, Pressable } from 'react-native';
import React from 'react';
import { useAuth } from '@/features/auth';
import { useTranslation } from 'react-i18next';
import { LinearGradient } from 'expo-linear-gradient';
import { Link } from 'expo-router';
import Constants from 'expo-constants';

const Profile = () => {
  const { t } = useTranslation();
  const { signOut, session } = useAuth();

  const handleLogout = async () => {
    try {
      await signOut();
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  const handleDeleteAccount = async () => {
    try {
      console.info('Deleting account...');
    } catch (error) {
      console.error('Error deleting account:', error);
    }
  };

  return (
    <SafeAreaView className="flex-1 bg-ocean">
      <View className="h-fit items-start justify-start border-b border-black-100/20 bg-ocean-dark px-4 py-4">
        <Text className="text-2xl font-bold text-linen">{t('profile.title')}</Text>

        <LinearGradient
          colors={['#000', 'transparent']}
          style={{
            position: 'absolute',
            bottom: -20,
            left: 0,
            right: 0,
            height: 20,
            zIndex: 100,
          }}
        />
      </View>
      <View className="flex-1 gap-8 px-2 py-8">
        <View className="space-y-4">
          <Text className="text-lg font-semibold text-linen">{t('profile.userInfoTitle')}</Text>
          <View className="rounded-lg border border-black-100/30 bg-ocean-dark p-4">
            <View className="space-y-4">
              <View className="flex-row justify-between">
                <Text className="text-base text-gray-300">{t('profile.name')}</Text>
                <Text className="text-base font-medium text-white">
                  {session?.user?.name} {session?.user?.lastName}
                </Text>
              </View>
              <View className="flex-row justify-between">
                <Text className="text-base text-gray-300">{t('profile.email')}</Text>
                <Text className="text-base font-medium text-white">{session?.user?.email}</Text>
              </View>
              {session?.user?.organization && (
                <>
                  <View className="flex-row justify-between">
                    <Text className="text-base text-gray-300">{t('profile.organization')}</Text>
                    <Text className="text-base font-medium text-white">{session?.user?.organization}</Text>
                  </View>
                  <View className="flex-row justify-between">
                  <Text className="text-base text-gray-300">{t('profile.licenseStatus')}</Text>
                    <View className="flex-row items-center gap-2">
                      <View className={`h-3 w-3 rounded-full ${session?.user?.hasLicense ? 'bg-green-500' : 'bg-red-500'}`} />
                      <Text className="text-base font-medium text-white">
                        {session?.user?.hasLicense ? t('profile.hasLicense') : t('profile.noLicense')}
                      </Text>
                    </View>
                  </View>
                </>
              )}
            </View>
          </View>
        </View>

        <View className="space-y-4">
          <Text className="text-lg font-semibold text-linen">{t('profile.settingsTitle')}</Text>
          <View className="gap-4">
            <Link href="/settings/contact" asChild>
              <Pressable className="rounded-lg border border-black-100/30 bg-ocean-dark p-4">
                <Text className="text-base font-medium text-white">📬 {t('profile.contact')}</Text>
              </Pressable>
            </Link>

            <Link href="/settings/privacy-policy" asChild>
              <Pressable className="rounded-lg border border-black-100/30 bg-ocean-dark p-4">
                <Text className="text-base font-medium text-white">🔐 {t('profile.privacy')}</Text>
              </Pressable>
            </Link>
            <Link href="/settings/purchase-policy" asChild>
              <Pressable className="rounded-lg border border-black-100/30 bg-ocean-dark p-4">
                <Text className="text-base font-medium text-white">{t('profile.extraChat.title')}</Text>
              </Pressable>
            </Link>
          </View>
        </View>

        <View className="gap-4 space-y-4">
          <Text className="text-lg font-semibold text-linen">{t('profile.securityTitle')}</Text>
          <Pressable className="rounded-lg bg-primary-200 p-4" onPress={handleLogout}>
            <Text className="text-center font-semibold text-black">{t('profile.logout')}</Text>
          </Pressable>

          <Pressable className="rounded-lg bg-red-600 p-4" onPress={handleDeleteAccount}>
            <Text className="text-center font-semibold text-white">
              {t('profile.deleteAccount')}
            </Text>
          </Pressable>
          <Text>v{Constants.expoConfig?.version ?? 'N/A'}</Text>
        </View>
      </View>
    </SafeAreaView>
  );
};

export default Profile;
