import { View, Text, Image, ScrollView, ActivityIndicator, Pressable } from 'react-native';
import { X } from 'lucide-react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { useUpdateCourseStatusMutation } from '@/features/education';
import HtmlRenderer from '@/app/components/ui/html-renderer';
import React, { useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useCoursePurchase } from '@/features/education/use-course-purchase';
import { useAuth } from '@/features/auth';

const CourseDetailScreen = () => {
  const { courseId, courseString } = useLocalSearchParams();
  const course = JSON.parse(courseString as string);
  const { t } = useTranslation();
  const { session } = useAuth();

  console.log('session', session);

  const { mutateAsync } = useUpdateCourseStatusMutation();
  const { isPurchasing, hasAccess, purchase, checkAccess } = useCoursePurchase(courseId as string, 'course');

  // Calculate if user has access to this course
  const userHasAccess = useMemo(() => {
    // If user has license, they have access to all courses
    if (session?.user?.hasLicense) {
      return true;
    }
    // If course is free, everyone has access
    if (course.price === 0) {
      return true;
    }
    // If course is already purchased, user has access
    if (course.isPurchased) {
      return true;
    }
    // Check if user has purchased this specific course
    return hasAccess;
  }, [session?.user?.hasLicense, course.price, course.isPurchased, hasAccess]);

  const handleStartCourse = async () => {
    // If user doesn't have access and course is paid, try to purchase
    if (!userHasAccess && course.price > 0) {
      const purchased = await purchase();
      if (!purchased) return;
    }

    router.back();
    await mutateAsync({ courseId: Number(courseId), status: 'in_progress' });
    router.push(`/(course)/${courseId}/outline` as any);
  };

  const courseStatusMessage = useMemo(() => {
    if (!course) return null;

    const { price, status } = course;
    let messageKey: string | null = null;

    if (price === 0 && status === 'not_started') {
      messageKey = 'courseDetail.freeAccess';
    } else if (status === 'in_progress') {
      messageKey = 'courseDetail.inProgress';
    } else if (status === 'completed') {
      messageKey = 'courseDetail.completed';
    }

    return messageKey ? (
      <Text className="text-center text-2xl font-semibold text-gray-700">{t(messageKey)}</Text>
    ) : null;
  }, [course, t]);

  const startButtonTitle = useMemo(() => {
    if (!course) return t('courseDetail.start');

    // If user doesn't have access and course is paid, show purchase button
    if (!userHasAccess && course.price > 0) {
      return t('courseDetail.unlock', { price: course.price });
    }

    // If user has access, show appropriate action based on course status
    switch (course.status) {
      case 'not_started':
        return t('courseDetail.start');
      case 'in_progress':
        return t('courseDetail.continue');
      case 'completed':
        return t('courseDetail.restart');
      default:
        return t('courseDetail.start');
    }
  }, [course, t, userHasAccess]);

  if (!course) {
    return (
      <View className="flex-1 items-center justify-center bg-linen p-4">
        <Text className="text-center text-red-500">Course not found.</Text>
        <Pressable onPress={() => router.back()} className="mt-4 rounded bg-gray-200 px-4 py-2">
          <Text className="font-semibold text-gray-700">Go Back</Text>
        </Pressable>
      </View>
    );
  }

  return (
    <ScrollView className="relative flex-1 bg-linen">
      <Pressable
        onPress={() => router.back()}
        className="absolute right-3 top-3 z-10 rounded-full bg-ocean-dark p-2"
      >
        <X size={24} color="#9FAA87" />
      </Pressable>

      {course.imageUrl && (
        <Image source={{ uri: course.imageUrl }} className="h-64 w-full object-cover" />
      )}

      <View className="p-6">
        <Text className="mb-3 text-3xl font-extrabold text-gray-900">{course.title}</Text>

        <Text className="mb-4 text-base leading-relaxed text-gray-700">
          <HtmlRenderer html={course.description} />
        </Text>

        {(!userHasAccess && course.price > 0) && (
          <View>
            <Text className="text-center text-4xl font-bold text-ocean">
              {t('courseDetail.unlock', { price: course.price })}
            </Text>
          </View>
        )}

        <View className="my-4">{courseStatusMessage}</View>

        <View className="flex-row justify-between gap-4">
          <Pressable
            onPress={() => router.back()}
            className="flex-1 rounded-lg bg-sage py-3 shadow "
          >
            <Text className="text-center text-lg font-semibold text-white">
              {t('courseDetail.close')}
            </Text>
          </Pressable>

          <Pressable
            onPress={handleStartCourse}
            className="flex-1 rounded-lg bg-sage py-3 shadow"
            disabled={isPurchasing}
          >
            <Text className="text-center text-lg font-semibold text-white">
              {isPurchasing ? t('courseDetail.loading') : startButtonTitle}
            </Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  );
};

export default CourseDetailScreen;
