import { View, Text, Pressable, ScrollView, ActivityIndicator } from 'react-native';
import React, { useState } from 'react';
import { router, useLocalSearchParams } from 'expo-router';
import { SafeAreaView } from 'react-native-safe-area-context';
import { ArrowLeft, FileText } from 'lucide-react-native';
import { useNewsByIdQuery } from '@/features/news/useNewsQuery';
import { Linking } from 'react-native';
import { RenderHTML } from 'react-native-render-html';
import { useWindowDimensions } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';

import SmartImage from '@/app/components/ui/smart-image';
import { useTranslation } from 'react-i18next';

function NewsItem() {
  const { t } = useTranslation();
  const { id } = useLocalSearchParams();
  const { data: news, isLoading, error } = useNewsByIdQuery(id as string);
  const { width } = useWindowDimensions();
  const [imageAspectRatio, setImageAspectRatio] = useState(1);

  if (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'An error occurred while loading news';
    return (
      <SafeAreaView className="flex-1 bg-black" edges={['top']}>
        <View className="h-fit flex-row items-start justify-start gap-2 border-b border-white/10 bg-black px-4 py-4">
          <Pressable onPress={() => router.back()}>
            <ArrowLeft size={24} color="#FFFFFF" />
          </Pressable>
          <Text className="text-2xl font-bold text-white">{t('news.news')}</Text>
        </View>
        <View className="flex-1 items-center justify-center">
          <Text className="text-lg text-white">Error: {errorMessage}</Text>
        </View>
      </SafeAreaView>
    );
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  const handleOpenPdf = (url: string) => {
    Linking.openURL(url).catch(err => console.error('Error opening PDF:', err));
  };

  // Add explicit check for news being null or undefined
  if (!news) {
    return (
      <SafeAreaView className="flex-1 bg-black" edges={['top']}>
        <View className="h-fit flex-row items-start justify-start gap-2 border-b border-white/10 bg-black px-4 py-4">
          <Pressable onPress={() => router.back()}>
            <ArrowLeft size={24} color="#FFFFFF" />
          </Pressable>
          <Text className="text-2xl font-bold text-white">{t('news.news')}</Text>
        </View>
        <View className="flex-1 items-center justify-center">
          <Text className="text-lg text-white">{t('news.noNews')}</Text>
        </View>
      </SafeAreaView>
    );
  }

  // HTML content style
  const htmlStyles = {
    body: {
      color: 'white',
      fontSize: 16,
      lineHeight: 24,
    },
    p: {
      marginBottom: 0,
    },
    a: {
      color: '#3498db',
    },
  };

  return (
    <SafeAreaView className="flex-1 bg-ocean-dark" edges={['top']}>
      <View className="h-fit flex-row items-center justify-start gap-2 border-b border-black-100/20 bg-ocean-dark px-4 py-4">
        <Pressable onPress={() => router.back()}>
          <ArrowLeft size={24} color="#FAF3ED" />
        </Pressable>
        <Text className="text-2xl font-bold text-linen">{t('news.news')}</Text>
      </View>
      <View className="relative flex-1 bg-ocean">
        {isLoading ? (
          <View className="flex-1 items-center justify-center bg-black">
            <ActivityIndicator size="large" color="#FFFFFF" />
          </View>
        ) : (
          <ScrollView className="flex-1 bg-ocean">
            <View className="relative w-full items-center bg-black">
              <SmartImage
                source={{ uri: news.featuredImage }}
                contentFit="cover"
                style={{
                  width: '100%',
                  aspectRatio: imageAspectRatio,
                }}
                priority="high"
              />
              <LinearGradient
                colors={['transparent', 'black']}
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  height: 50,
                }}
              />
            </View>

            <View className="px-4 pb-40">
              <Text className="py-2 text-gray-400">
                {news.createdAt ? formatDate(news.createdAt) : ''}
              </Text>
              <Text className="mb-2 text-2xl font-bold text-white">{news.title}</Text>

              <View className="mb-4 flex-row justify-between">
                {news.userName && (
                  <Text className="text-gray-400">
                    {t('news.by')}: {news.userName}
                  </Text>
                )}
              </View>

              {/* Render HTML content instead of plain text */}
              {news.content && (
                <View className="mb-6">
                  <RenderHTML
                    contentWidth={width - 32} // Account for padding
                    source={{ html: news.content }}
                    tagsStyles={htmlStyles}
                  />
                </View>
              )}

              {news.pdfFiles && news.pdfFiles.length > 0 && (
                <View className="mt-4">
                  <Text className="mb-2 text-lg font-semibold text-white">
                    {t('news.attachments')}:
                  </Text>
                  {news.pdfFiles.map(pdf => (
                    <Pressable
                      key={pdf.s3Key}
                      className="mb-2 flex-row items-center rounded-lg bg-gray-800 px-4 py-3"
                      onPress={() => handleOpenPdf(pdf.s3Url)}
                    >
                      <FileText size={20} color="#FFFFFF" />
                      <View className="ml-3">
                        <Text className="text-white">{pdf.fileName}</Text>
                        <Text className="text-xs text-gray-400">
                          {(pdf.fileSize / (1024 * 1024)).toFixed(2)} MB
                        </Text>
                      </View>
                    </Pressable>
                  ))}
                </View>
              )}
            </View>
          </ScrollView>
        )}
      </View>
    </SafeAreaView>
  );
}

export default NewsItem;
