import { useCallback } from 'react';
import { View, Text, Pressable, FlatList, SafeAreaView } from 'react-native';
import { useLocalSearchParams, useRouter, useFocusEffect, Link } from 'expo-router';
import { useCourseByIdQuery } from '@/features/education';
import { getChapterStatus } from '@/features/education/utils/get-chapter-status';

import React from 'react';
import { ArrowLeft } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';

const CourseOutlineScreen = () => {
  const { courseId } = useLocalSearchParams<{ courseId: string }>();
  const { data: course, refetch } = useCourseByIdQuery(courseId);

  useFocusEffect(
    useCallback(() => {
      refetch();
    }, [refetch]),
  );

  const router = useRouter();
  const renderChapterItem = ({ item }) => {
    const chapterStatus = getChapterStatus(item);
    const isCompleted = chapterStatus === 'completed';
    return (
      <Link href={`/(course)/${courseId}/lesson/${item.chapterId}`} asChild>
        <Pressable
          className={`rounded-lg border p-4 shadow ${
            isCompleted ? 'border-green-300 bg-green-200' : 'border-linen-200 bg-linen'
          }`}
        >
          <Text className="text-lg text-blue-600">{item.title}</Text>
        </Pressable>
      </Link>
    );
  };

  return (
    <SafeAreaView className="flex-1 bg-ocean">
      <View className="h-fit flex-row items-center justify-start gap-2 border-b border-black-100/20 bg-ocean-dark px-2 py-4">
        <Pressable onPress={() => router.back()}>
          <ArrowLeft size={24} color="#FAF3ED" />
        </Pressable>
        <Text className="text-2xl font-bold text-linen">{course?.title}</Text>
        <LinearGradient
          colors={['#000', 'transparent']}
          style={{
            position: 'absolute',
            bottom: -20,
            left: 0,
            right: 0,
            height: 20,
            zIndex: 100,
          }}
        />
      </View>
      <View className="flex-1 py-8">
        <FlatList
          className="p-2"
          data={course?.chapters}
          renderItem={renderChapterItem}
          keyExtractor={item => item.chapterId}
          ItemSeparatorComponent={() => <View className="h-3" />}
        />
      </View>
    </SafeAreaView>
  );
};

export default CourseOutlineScreen;
