import React, { useMemo } from 'react';
import { View, Text, Pressable } from 'react-native';
import { useForm, Controller, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useTranslation } from 'react-i18next';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { Question } from '@/features/education/types';
import HtmlRenderer from '@/app/components/ui/html-renderer';

// Define the schema for a single question answer
const questionAnswerSchema = z.object({
  questionId: z.number(),
  selectedOptionId: z.number().nullable(),
});

// Define the overall form schema
const formSchema = z.object({
  answers: z.array(questionAnswerSchema),
});

interface QuestionFormProps {
  questions: Question[];
  onSubmit: () => void;
  hideSubmitButton: boolean;
}

const QuestionForm = ({ questions, onSubmit, hideSubmitButton }: QuestionFormProps) => {
  const { t } = useTranslation();

  const defaultValues = {
    answers: questions.map(q => ({
      questionId: q.questionId,
      selectedOptionId: q.userAnswerOptionIds?.[0] ?? null,
    })),
  };

  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: zodResolver(formSchema),
    defaultValues,
  });

  const answers = useWatch({ control, name: 'answers' });

  const initialAnswers = defaultValues.answers;

  const changedAnswers = useMemo(() => {
    if (!answers) return [];
    return answers.filter(
      (a, index) => a.selectedOptionId !== initialAnswers[index]?.selectedOptionId,
    );
  }, [answers, initialAnswers]);

  const isSubmitDisabled = answers?.some(answer => answer.selectedOptionId === null);
  const isFormChanged = changedAnswers.length > 0;

  const onSubmitHandler = () => {
    const result = isFormChanged ? changedAnswers : initialAnswers;
    onSubmit(
      result.map(({ questionId, selectedOptionId }) => ({
        questionId,
        option_id: selectedOptionId,
      })),
    );
  };

  return (
    <View className="flex-1">
      {questions.map((question, index) => (
        <View key={question.questionId} className="mb-6 rounded-lg bg-linen p-4 shadow-md">
          <View className="mb-4 text-lg font-bold text-gray-800">
            <HtmlRenderer html={question.text} />
          </View>
          <Controller
            control={control}
            name={`answers.${index}.selectedOptionId`}
            render={({ field: { onChange, value } }) => (
              <View className="flex-col">
                {question.options.map(option => {
                  const isSelected = value === option.optionId;
                  const hasAnswered = question.userAnswerOptionIds?.length > 0;
                  const isUserAnswer = question.userAnswerOptionIds?.includes(option.optionId);
                  const isCorrect = option.isCorrect;

                  let optionStyle = 'bg-gray-200 border-gray-300';
                  let textStyle = 'text-gray-700';

                  if (hasAnswered && isUserAnswer) {
                    if (isCorrect) {
                      optionStyle = 'bg-green-100 border-green-500';
                      textStyle = 'text-green-800 font-bold';
                    } else {
                      optionStyle = 'bg-red-100 border-red-500';
                      textStyle = 'text-red-800 font-bold';
                    }
                  } else if (isSelected) {
                    optionStyle = 'bg-green-50 border-green-500';
                    textStyle = 'text-gray-900 font-bold';
                  }

                  return (
                    <Pressable
                      key={option.optionId}
                      className={`mb-2 flex-row items-center rounded-lg border px-4 py-3 ${optionStyle}`}
                      onPress={() => onChange(option.optionId)}
                      disabled={hasAnswered}
                    >
                      <Text className={`flex-1 text-base ${textStyle}`}>{option.text}</Text>
                      {isSelected && !hasAnswered && (
                        <MaterialCommunityIcons
                          name="check-circle"
                          size={20}
                          color="#28a745"
                          className="ml-2"
                        />
                      )}
                      {hasAnswered && isUserAnswer && (
                        <MaterialCommunityIcons
                          name={isCorrect ? 'check-circle' : 'close-circle'}
                          size={20}
                          color={isCorrect ? '#28a745' : '#e53935'}
                          className="ml-2"
                        />
                      )}
                    </Pressable>
                  );
                })}
              </View>
            )}
          />
          {errors.answers?.[index]?.selectedOptionId && (
            <Text className="mt-1 text-sm text-red-600">
              {t('questionForm.validation.selectOption')}
            </Text>
          )}
        </View>
      ))}

      {hideSubmitButton && (
        <Pressable
          onPress={handleSubmit(onSubmitHandler)}
          className="mt-8 overflow-hidden rounded-lg"
          disabled={isSubmitDisabled}
        >
          <LinearGradient
            colors={isSubmitDisabled ? ['#A0A0A0', '#A0A0A0'] : ['#4CAF50', '#28a745']}
            className="rounded-lg shadow"
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
          >
            <View className="flex-row items-center justify-center px-5 py-3">
              <Text className="mr-2 text-lg font-bold text-white">{t('questionForm.submit')}</Text>
              <MaterialCommunityIcons name="send" size={20} color="white" />
            </View>
          </LinearGradient>
        </Pressable>
      )}
    </View>
  );
};

export default QuestionForm;
