import 'react-native-get-random-values';
import { v4 as uuidv4 } from 'uuid';
import { View, Text, Pressable, KeyboardAvoidingView, Platform, Alert } from 'react-native';
import React, { useState } from 'react';
import { ArrowLeft } from 'lucide-react-native';
import { useTranslation } from 'react-i18next';
import { router } from 'expo-router';
import { useChat } from '@ai-sdk/react';
import Messages from './messages';
import { SafeAreaView } from 'react-native-safe-area-context';
import { fetch as expoFetch } from 'expo/fetch';
import { LinearGradient } from 'expo-linear-gradient';
import { ChatInput } from '@/app/components/ui/exports';
import type { ChatInterfaceProps } from '@/features/chats/types';
import { checkTokenAvailability } from '@/features/chats/use-chats-query';
import { useCoursePurchase } from '@/features/education/use-course-purchase';

const ChatInterface = ({ id, initialMessages, userId }: ChatInterfaceProps) => {
  const [isUsingTool, setIsUsingTool] = useState(false);
  const [isCheckingTokens, setIsCheckingTokens] = useState(false);
  const { t } = useTranslation();
  const { isPurchasing, purchase } = useCoursePurchase('75', 'token');

  const { messages, setMessages, input, setInput, append, status, reload } = useChat({
    id,
    headers: {
      'User-ID': userId,
    },
    fetch: expoFetch as unknown as typeof globalThis.fetch,
    api: 'https://kb.intressebevakaren.se/api/chat',
    body: { id },
    initialMessages,
    experimental_throttle: 100,
    sendExtraMessageFields: true,
    generateId: () => uuidv4(),
    onToolCall: () => {
      setIsUsingTool(true);
    },
    onFinish: () => {
      setIsUsingTool(false);
    },
    onError: error => {
      if (error?.message?.includes('TOKEN_QUOTA_EXCEEDED')) {
        Alert.alert(t('chat.limit_title'), t('chat.limit_message'), [{ text: t('chat.limit_ok') }]);
      }
      setIsUsingTool(false);
    },
  });

  // Custom submit handler to check token availability before sending
  const handleCustomSubmit = async (text: string) => {
    if (isCheckingTokens || isPurchasing) {
      return; // Prevent multiple simultaneous checks
    }

    setIsCheckingTokens(true);

    try {
      // Make a fresh API call to check token availability
      const tokenAvailability = await checkTokenAvailability(userId);

      if (!tokenAvailability.available) {
        Alert.alert(t('chat.no_tokens_title'), t('chat.no_tokens_message'), [
          {
            text: t('chat.buy_tokens'),
            onPress: async () => {
              const purchased = await purchase();
              if (purchased) {
                // Retry sending the message after successful purchase
                // Use append instead of handleSubmit for better control
                await append({
                  id: uuidv4(),
                  role: 'user',
                  content: text,
                });
                // Clear input after successful send
                setInput('');
              }
            },
          },
          {
            text: t('chat.cancel'),
            onPress: () => console.log('Cancel Pressed'),
            style: 'cancel',
          },
        ]);
        return;
      }

      // Proceed with normal submit if tokens are available
      // Use append instead of handleSubmit for better control
      await append({
        id: uuidv4(),
        role: 'user',
        content: text,
      });
      // Clear input after successful send
      setInput('');
    } catch (error) {
      console.error('Error checking token availability:', error);
      Alert.alert(t('chat.error_title'), t('chat.error_checking_tokens'), [{ text: t('chat.ok') }]);
    } finally {
      setIsCheckingTokens(false);
    }
  };

  return (
    <View className="flex-1">
      <View className="absolute inset-0 bg-ocean-dark" />
      <View className="absolute left-0 right-0 top-0 h-[120px] bg-ocean-dark" />
      <SafeAreaView className="flex-1" edges={['top', 'bottom']}>
        <View className="h-fit flex-row items-center justify-start gap-2 border-b border-black-100/20 px-4 py-4">
          <Pressable onPress={() => router.push('/(app)/dashboard')}>
            <ArrowLeft size={24} color="#FAF3ED" />
          </Pressable>
          <Text className="text-2xl font-bold text-linen">{t('chat.title')}</Text>
        </View>

        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
          className="flex-1"
          keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 0}
        >
          <View className="relative flex-1 bg-ocean">
            <LinearGradient
              colors={['#000', 'transparent']}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: 20,
                zIndex: 100,
              }}
            />

            <View className="mx-4 mb-2 mt-4 rounded-md border border-yellow-300 bg-yellow-100 px-4 py-3">
              <Text className="text-sm font-medium text-black">{t('chat.warning')}</Text>
            </View>

            <Messages
              chatId={id}
              status={status}
              messages={messages}
              setMessages={setMessages}
              reload={reload}
              isUsingTool={isUsingTool}
              append={append}
            />

            <ChatInput
              onSubmit={handleCustomSubmit}
              placeholder={t('chat.placeholder')}
              disabled={status === 'streaming' || isCheckingTokens || isPurchasing}
              value={input}
              onChangeText={setInput}
            />
          </View>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </View>
  );
};

export default ChatInterface;
