import React from 'react';
import { View, ActivityIndicator, FlatList } from 'react-native';
import { useCertificatesQuery } from '@/features/education/use-certificate';
import CertificateListItem from './certificate-list-item';

const ListAllCertificates = () => {
  const { data, isLoading, refetch } = useCertificatesQuery();

  if (isLoading) {
    return (
      <View className="flex-1 items-center justify-center py-4">
        <ActivityIndicator size="large" color="#fff" />
      </View>
    );
  }

  if (!data?.length) {
    return null;
  }

  return (
    <View className="flex-1 px-2 pt-6">
      <FlatList
        data={data}
        renderItem={({ item }) => <CertificateListItem item={item} />}
        scrollEnabled={true}
        onRefresh={refetch}
        refreshing={isLoading}
        showsVerticalScrollIndicator={false}
      />
    </View>
  );
};

export default ListAllCertificates;
