import React from 'react';
import { useLocalSearchParams } from 'expo-router';
import ChatInterface from '@/app/components/chat/chat-interface';
import { View, Text, ActivityIndicator } from 'react-native';
import { useChatByIdQuery, useChatsQuery } from '@/features/chats/use-chats-query';
import { useAuth } from '@/features/auth';
import type { Message } from 'ai';

const LenaChat = () => {
  const { id } = useLocalSearchParams();
  const { session } = useAuth();

  const { data, isLoading, error } = useChatByIdQuery(id as string);

  if (isLoading) {
    return (
      <View className="flex-1 items-center justify-center bg-black">
        <ActivityIndicator size="large" color="#ffffff" />
      </View>
    );
  }

  if (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'An error occurred while loading chat';
    return (
      <View className="flex-1 items-center justify-center">
        <Text>Error: {errorMessage}</Text>
      </View>
    );
  }

  if (!data) {
    return (
      <View className="flex-1 items-center justify-center">
        <Text>No chat data found</Text>
      </View>
    );
  }

  // Convert string dates to Date objects for initialMessages
  const initialMessages: Message[] =
    data.messages?.map((message: any) => ({
      ...message,
      createdAt: new Date(message.createdAt),
    })) || [];

  return (
    <ChatInterface
      id={data.chat?.id as string}
      initialMessages={initialMessages}
      userId={session?.user?.id}
    />
  );
};
export default LenaChat;
